  asyncTimeout?: number,

  /** Event handler for button press events. */
  onPress?: undefined | (() => void | Promise<void>),
}>;
/**
 * Button component.
 */
export const Button = (props: ButtonProps) => {
  const {
    children,
    unstyled = false,
    trimmed = false,
    label,
    icon,
    kind = 'tertiary',
    variant = 'normal',
    disabled = false,
    nonactive = false,
    onPress,
    asyncTimeout = 30_000,
    ...propsRest
