            </>
          );
        }}
      </MenuProvider>
    );
  },
  {
    Static: MenuProvider.Static,
    Option: MenuProvider.Option,
    Header: MenuProvider.Header,
    Action: MenuProvider.Action,
    FooterActions: MenuProvider.FooterActions,
  },
);

