          return assertUnreachable(placement);
      }
    })();

    return (
      <Tooltip
        {...mergeProps(floatingProps, tooltipProps)}
        ref={mergeRefs<HTMLDivElement>(
          refs.setFloating,
          floatingProps.ref as React.Ref<HTMLDivElement>,
